	"openProjectSession",
	"getSession",
	"getProjectOutline",
	"queryEntity",
	"readSessionState",
	"readResourceBytes",
	"validateSession",
	"preflightTransaction",
	"applyTransaction",
	"saveSession",
	"materializeSession",
	"closeSession",
	"getEvents",
	"getCacheSnapshot",
	"refreshCache"
