//#region src/runtime.ts
var BackendRuntime = class {
	fileSystem;
	capabilities;
	sessions;
	sessionOperations = new SessionOperationQueue();
	context;
	readService;
	runtimeService;
	authoringService;
	persistenceService;
	cacheService;
	eventService;
	constructor(options = {}) {
		this.fileSystem = options.fileSystem;
		const maxSessions = options.maxSessions ?? 32;
		if (!Number.isSafeInteger(maxSessions) || maxSessions < 1) throw new RangeError(`maxSessions must be a positive integer: ${maxSessions}`);
		const idleTimeout = options.idleSessionTimeoutMs ?? 30 * 6e4;
		if (!Number.isSafeInteger(idleTimeout) || idleTimeout < 0 || idleTimeout > 2147483647) throw new RangeError("idleSessionTimeoutMs must be an integer between 0 and 2147483647.");
		this.sessions = new SessionRegistry(maxSessions, idleTimeout, (sessionId, activity) => this.runtimeService.expireIdleSession(sessionId, activity));
		this.capabilities = createCapabilities(Boolean(options.fileSystem?.runProjectWriteTransaction), options.fileSystem?.caseSensitivePaths ?? false, maxSessions, idleTimeout);
		this.context = {
			fileSystem: this.fileSystem,
			host: options.host,
			allowedProjectRoots: options.allowedProjectRoots,
			capabilities: this.capabilities,
			sessions: this.sessions
		};
		const getSession = (sessionId) => this.sessions.get(sessionId);
		this.readService = new ReadService((sessionId) => readView(getSession(sessionId)), this.capabilities);
		this.eventService = new EventService(getSession);
		this.cacheService = new CacheService(getSession, this.eventService);
		this.runtimeService = new RuntimeService(this.context, this.cacheService, this.eventService, this.sessionOperations);
		this.authoringService = new AuthoringService(this.context, this.cacheService, this.eventService, this.sessionOperations);
		this.persistenceService = new PersistenceService(this.context, this.cacheService, this.eventService, this.sessionOperations);
	}
	getCapabilities() {
		return this.readService.getCapabilities();
	}
	async openSession(input) {
		const startedAt = Date.now();
		try {
			return await this.runtimeService.openSession(input);
		} catch (error) {
			return failure("runtime", startedAt, {
				code: "project_open_failed",
				...classifyProjectOpenFailure(error),
				projectPath: input.projectPath
			});
		}
	}
	openProjectSession(input) {
		return this.runtimeService.openProjectSession(input);
	}
	getSession(input) {
		return this.readService.getSession(input);
	}
	getProjectOutline(input) {
		return this.readService.getProjectOutline(input);
	}
	queryEntity(input) {
		return this.readService.queryEntity(input);
	}
	readSessionState(input) {
		return this.readService.readSessionState(input);
	}
	readResourceBytes(input) {
		return this.readService.readResourceBytes(input);
	}
	validateSession(input) {
		return this.readService.validateSession(input);
	}
	async preflightTransaction(input) {
		return this.authoringService.preflightTransaction(input);
	}
	async applyTransaction(input) {
		return this.authoringService.applyTransaction(input);
	}
	async saveSession(input) {
		return this.persistenceService.saveSession(input);
	}
	async materializeSession(input) {
		return this.persistenceService.materializeSession(input);
	}
	async closeSession(input) {
		const captured = { ...input };
		return this.sessionOperations.run(captured.sessionId, () => this.runtimeService.closeSession(captured));
	}
	getEvents(input) {
		return this.eventService.getEvents(input);
	}
	getCacheSnapshot(input) {
		return this.cacheService.getCacheSnapshot(input);
	}
	refreshCache(input) {
		return this.cacheService.refreshCache(input);
	}
};
